class Solution {
public:
 int pairSum(ListNode* head){
  ListNode* slow=head,*fast=head;
  while(fast && fast->next){slow=slow->next;fast=fast->next->next;}
  ListNode* rev=nullptr;
  while(slow){ListNode* next=slow->next;slow->next=rev;rev=slow;slow=next;}
  int ans=0;for(ListNode* p=head;rev;p=p->next,rev=rev->next)ans=max(ans,p->val+rev->val);
  return ans;
 }
};
